  function actionButton(text2, action2, className = "academy-button academy-button-secondary") {
    const button2 = element("button", className);
    button2.type = "button";
    button2.textContent = text2;
    button2.addEventListener("click", () => {
      button2.disabled = true;
      button2.setAttribute("aria-busy", "true");
      void action2(button2).catch((error) => {
        const status2 = button2.closest(".academy-profile-sync-screen")?.querySelector(".academy-profile-sync-status");
        if (!status2) return;
        status2.setAttribute("role", "alert");
        status2.setAttribute("aria-live", "assertive");
        status2.dataset.phase = "error";
        const title2 = status2.querySelector(".academy-profile-sync-status-title");
        const detail = status2.querySelector(".academy-profile-sync-status-detail");
        const language2 = button2.closest(".academy-profile-sync-screen")?.lang === "ja" ? "ja" : "en";
        if (title2) title2.textContent = phaseTitle("error", language2);
        if (detail) detail.textContent = error instanceof Error ? error.message : localize(language2, "This action could not finish. Try again.", "操作を完了できませんでした。もう一度試してください。");
      }).finally(() => {
        button2.disabled = false;
        button2.removeAttribute("aria-busy");
      });
    });
    return button2;
  }
  function phaseTitle(phase, language2) {
    const titles = {
      local: ["Local only", "ローカルのみ"],
      "sign-in": ["Google sign-in required", "Google サインインが必要"],
      recovery: ["Starting recovery", "復旧を開始中"],
      "signed-out": ["Signed out", "サインアウト済み"],
      pending: ["Activation pending", "有効化を待っています"],
      claimed: ["Purchase activated", "購入を有効化しました"],
      pair: ["Pairing required", "ペアリングが必要"],
      conflict: ["Account conflict", "アカウントの競合"],
      syncing: ["Syncing", "同期中"],
      ready: ["Synced", "同期済み"],
      offline: ["Offline", "オフライン"],
      retry: ["Sync interrupted", "同期が中断されました"],
      error: ["Action needed", "操作が必要"]
    };
    return localize(language2, titles[phase][0], titles[phase][1]);
  }
  function statusText(status2, language2) {
    if (status2.error) return status2.error;
    if (status2.phase === "local") return status2.profile ? localize(language2, "Encrypted history is ready on this device.", "この端末に暗号化された履歴があります。") : localize(language2, "No server profile has been created.", "サーバープロフィールは作成されていません。");
    if (status2.phase === "sign-in") return localize(language2, "Sign in with Google to continue. Every Academy invitation, including class invitations, is linked to a Google account.", "Google にサインインして続けてください。クラスの招待コードを含め、すべての Academy 招待は Google アカウントとリンクされます。");
    if (status2.phase === "recovery") return localize(language2, "Opening Google sign-in for account recovery.", "アカウント復旧のため Google サインインを開いています。");
    if (status2.phase === "signed-out") return localize(language2, "Your encryption key remains on this device for account recovery.", "アカウント復旧のため、暗号鍵はこの端末に保持されています。");
    if (status2.phase === "pending") return localize(language2, "Enter the paid code below. If payment just completed, activation may take a moment.", "下に有料コードを入力してください。支払い直後は、有効化まで少し時間がかかることがあります。");
    if (status2.phase === "claimed") return localize(language2, "This paid code is now linked to this Google account. Neither can be used for another activation.", "この有料コードは Google アカウントにリンクされました。コードもアカウントも別の有効化には使用できません。");
    if (status2.phase === "pair") return localize(language2, "Use a one-time code from a device that already has your encrypted history.", "暗号化された履歴がある端末のワンタイムコードを使ってください。");
    if (status2.phase === "conflict") return localize(language2, "A code and account can each be linked only once.", "コードとアカウントは、それぞれ一度だけリンクできます。");
    if (status2.phase === "offline") return localize(language2, `${status2.pending} encrypted event${status2.pending === 1 ? "" : "s"} waiting.`, `暗号化された記録 ${status2.pending} 件が待機中です。`);
    if (status2.phase === "syncing") return localize(language2, "Encrypting and exchanging events.", "記録を暗号化して同期しています。");
    if (status2.phase === "retry") return localize(language2, "Local learning is safe. Retry when the connection is stable.", "端末の学習記録は安全です。接続が安定したら再試行してください。");
    if (status2.phase === "error") return localize(language2, "Review the account state and try again.", "アカウントの状態を確認して、もう一度試してください。");
    const time = status2.lastSyncAt ? new Date(status2.lastSyncAt).toLocaleString() : null;
    return time ? `${localize(language2, "Last sync", "最終同期")}: ${time}` : localize(language2, "Encrypted history is up to date.", "暗号化された履歴は最新です。");
  }
  function localize(language2, en, ja) {
    return language2 === "ja" ? ja : en;
  }
