    const setCounterEnabled = (enabled) => {
      decrease.disabled = !enabled || count2 === 0;
      increase.disabled = !enabled || count2 === plan.maxCount;
    };
    const updateCount = () => {
      const yen = count2 * plan.denominationYen;
      amount.value = String(yen);
      amount.textContent = `¥${yen.toLocaleString("en-US")}`;
      notes.forEach((note, index) => note.classList.toggle("is-counted", index < count2));
      setCounterEnabled(listeningStarted && !complete);
    };
